const items = $input.all();
const invoices = (items[0] && items[0].json && items[0].json.data) ? items[0].json.data : [];
const now = Math.floor(Date.now() / 1000);

let bucket1_30 = 0;
let bucket31_60 = 0;
let bucket60_plus = 0;
let totalOverdue = 0;
let count = 0;

for (const inv of invoices) {
  if (!inv.due_date || inv.paid || inv.status !== 'open') continue;
  const days = Math.floor((now - inv.due_date) / 86400);
  if (days <= 0) continue;

  const amt = (inv.amount_due || 0) / 100;
  totalOverdue += amt;
  count++;

  if (days <= 30) bucket1_30 += amt;
  else if (days <= 60) bucket31_60 += amt;
  else bucket60_plus += amt;
}

return [{
  json: {
    month: new Date().toLocaleString('en-US', { month: 'long', year: 'numeric' }),
    totalOverdueCount: count,
    totalOverdueAmount: totalOverdue.toFixed(2),
    bucket1_30: bucket1_30.toFixed(2),
    bucket31_60: bucket31_60.toFixed(2),
    bucket60_plus: bucket60_plus.toFixed(2)
  }
}];

const data = $input.item.json;
const text = `💰 *Monthly Accounts Receivable Aging Report — ${data.month}*\n• *Total Overdue Invoices:* ${data.totalOverdueCount}\n• *Total Outstanding Amount:* $${data.totalOverdueAmount}\n\n*Aging Breakdown:*\n• 1–30 days: $${data.bucket1_30}\n• 31–60 days: $${data.bucket31_60}\n• 60+ days (Critical): $${data.bucket60_plus}`;

return {
  json: {
    slackPayload: {
      text: `Monthly Overdue Report: $${data.totalOverdueAmount} outstanding`,
      attachments: [{
        color: '#ff9900',
        text: text,
        footer: 'AutomateStack Monthly Chaser Report'
      }]
    }
  }
};
